(() => {
  const copy = {
    vi:{home:'Trang chủ',overview:'Tổng quan sản phẩm',collection:'HOTPRINT / THƯ VIỆN BAO BÌ',hero1:'Giải pháp bao bì',hero2:'cho dấu ấn riêng.',intro:'Từ một nếp gấp đến cách thương hiệu được cảm nhận. Khám phá những sản phẩm chúng tôi đã thực hiện, tìm cấu trúc phù hợp cho ý tưởng của bạn.',explore:'Khám phá 6 nhóm sản phẩm',actual:'Ảnh sản phẩm thực tế HotPrint',coverAlt:'Hộp quà họa tiết thực vật, ảnh sản phẩm thực tế HotPrint',familiesKicker:'01 / CHỌN CẤU TRÚC',familiesTitle:'Một hình thái. Một khả năng mới.',familiesIntro:'Bắt đầu từ sản phẩm cần chứa đựng.\nChúng tôi cùng bạn tìm cách thể hiện.',libraryKicker:'02 / NHỮNG SẢN PHẨM ĐÃ THỰC HIỆN',libraryTitle:'Chất liệu cho ý tưởng của bạn.',libraryIntro:'Những mẫu thật, những góc nhìn thật.\nChọn một mẫu để xem gần hơn.',searchLabel:'Tìm mẫu theo tên, thương hiệu hoặc mã ảnh',search:'Tìm kiếm',placeholder:'Tên mẫu, thương hiệu, mã ảnh…',filterGroup:'Lọc theo nhóm sản phẩm',filter:'Bộ lọc',clear:'Xóa bộ lọc ×',photoNote:'Ảnh gốc · Không thay đổi thiết kế sản phẩm',emptyTitle:'Chưa tìm thấy mẫu phù hợp.',emptyText:'Thử tên khác hoặc chia sẻ ý tưởng để HotPrint tư vấn cấu trúc phù hợp.',all:'Xem tất cả mẫu',referenceNote:'Mẫu được trưng bày để tham khảo cấu trúc và cách hoàn thiện. Thiết kế, kích thước, vật liệu và số lượng cho dự án của bạn được trao đổi riêng với HotPrint.',processKicker:'03 / TỪ THAM KHẢO ĐẾN RIÊNG BIỆT',processTitle:'Cùng bắt đầu từ một ý tưởng.',step1:'Chia sẻ nhu cầu',step1Text:'Sản phẩm cần đóng gói, số lượng dự kiến và mẫu bạn quan tâm.',step2:'Tìm cấu trúc phù hợp',step2Text:'Cùng trao đổi về vật liệu, kiểu hộp và cách thể hiện thương hiệu.',step3:'Thống nhất mẫu',step3Text:'Trao đổi điều kiện làm mẫu, kiểm tra và duyệt trước khi triển khai.',consultKicker:'DÀNH CHỖ CHO Ý TƯỞNG MỚI',consultTitle:'Chưa tìm thấy\ncấu trúc phù hợp?',consultText:'Mỗi sản phẩm có một yêu cầu riêng. Hãy kể cho chúng tôi về sản phẩm của bạn.',talk:'Trao đổi với HotPrint',largeImage:'Mở ảnh lớn ↗',detailNote:'Một mẫu tham khảo từ thư viện ảnh HotPrint. Hãy trao đổi với chúng tôi về cấu trúc và cách hoàn thiện cho thiết kế riêng của bạn.',detailProof:'Giữ nguyên ảnh sản phẩm và nhận diện thương hiệu trong ảnh gốc.',detailTerms:'Báo giá và điều kiện nhận mẫu được thống nhất trực tiếp. Không đặt hàng hay thanh toán trên trang này.',reset:'Đặt lại',apply:'Áp dụng',allGroups:'Tất cả nhóm sản phẩm',groupLink:'Xem nhóm sản phẩm',detail:'Xem chi tiết',sample:'Yêu cầu mẫu',photo:'Ảnh',ref:'Mã ảnh tham khảo',prev:'Trang trước',next:'Trang tiếp theo',page:'Trang',prevImage:'Ảnh trước',nextImage:'Ảnh tiếp theo',unavailable:'Ảnh chưa tải được. Chọn xem chi tiết hoặc liên hệ HotPrint.',pagination:'Phân trang sản phẩm'},
    en:{home:'Home',overview:'Product overview',collection:'HOTPRINT / THE PACKAGING LIBRARY',hero1:'Packaging solutions.',hero2:'Your own expression.',intro:'From a simple fold to the way a brand feels. Explore products we have made and find the right structure for your next idea.',explore:'Explore 6 product families',actual:'Actual HotPrint product photography',coverAlt:'Botanical gift box, actual HotPrint product photograph',familiesKicker:'01 / FIND YOUR STRUCTURE',familiesTitle:'One form. A new possibility.',familiesIntro:'Start with the product inside.\nTogether, we’ll find its expression.',libraryKicker:'02 / PRODUCTS WE HAVE MADE',libraryTitle:'A starting point for your ideas.',libraryIntro:'Real samples. Real perspectives.\nChoose a sample for a closer look.',searchLabel:'Find samples by name, brand or image reference',search:'Search',placeholder:'Sample, brand, image reference…',filterGroup:'Filter by product family',filter:'Filters',clear:'Clear filters ×',photoNote:'Original photography · Product designs preserved',emptyTitle:'No matching samples yet.',emptyText:'Try another name or share your idea so we can help you find the right structure.',all:'View all samples',referenceNote:'Samples illustrate structures and finishes. Design, dimensions, materials and quantities for your project are discussed individually with HotPrint.',processKicker:'03 / FROM REFERENCE TO YOUR OWN',processTitle:'Let’s start with an idea.',step1:'Share your needs',step1Text:'The product you need to package, expected quantities and samples that interest you.',step2:'Find the right structure',step2Text:'Explore materials, box styles and how to express your brand together.',step3:'Agree on a sample',step3Text:'Discuss sample conditions, review the details and approve before proceeding.',consultKicker:'MAKE ROOM FOR A NEW IDEA',consultTitle:'Still looking for\nthe right structure?',consultText:'Every product has its own requirements. Tell us about yours.',talk:'Talk to HotPrint',largeImage:'Open full image ↗',detailNote:'A reference sample from the HotPrint photo library. Talk to us about structure and finishing for your own design.',detailProof:'The product and brand identity are preserved as shown in the original photograph.',detailTerms:'Quotes and sample arrangements are agreed directly. This page does not place orders or take payments.',reset:'Reset',apply:'Apply',allGroups:'All product families',groupLink:'Explore this family',detail:'View details',sample:'Request a sample',photo:'Photo',ref:'Image reference',prev:'Previous page',next:'Next page',page:'Page',prevImage:'Previous image',nextImage:'Next image',unavailable:'Image could not load. View details or contact HotPrint.',pagination:'Product pagination'}
  };
  const $c = s=>document.querySelector(s), txt=k=>copy[language][k];
  const products=window.HOTPRINT_PRODUCTS;
  const imageURL=(id,large=false)=>`/assets/products/${id}${large?'-large':''}.webp`;
  const familyPhotos=['032A5315','032A5366','032A5293','032A5331','032A5339','032A5353'];
  const familyUses={vi:['Thực phẩm, mỹ phẩm, hàng tiêu dùng','Hộp thiết bị, bộ sản phẩm','Hộp quà, bộ sưu tập','Thời trang, quà tặng, bán lẻ','Tem cuộn, nhãn nhận diện','Thẻ treo, tài liệu thương hiệu'],en:['Food, beauty, consumer goods','Equipment and product sets','Gifts and collections','Fashion, gifting, retail','Roll labels and product identity','Hang tags and brand literature']};
  const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase();
  const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let selectedProduct=null, imageIndex=0, state;
  function readState(){const params=new URLSearchParams(location.search);return{q:(params.get('q')||'').slice(0,100),group:categories.some(c=>c.slug===params.get('group'))?params.get('group'):'',page:Math.max(1,Number.parseInt(params.get('page'),10)||1)};}
  function setURL(push=false){const url=new URL(location.href);for(const k of ['q','group','page']){if(state[k]&&(k!=='page'||state.page>1))url.searchParams.set(k,state[k]);else url.searchParams.delete(k);}history[push?'pushState':'replaceState']({},'',url.pathname+url.search+url.hash);document.querySelectorAll('[data-lang]').forEach(a=>a.href=productsPath(a.dataset.lang)+url.search+url.hash);}
  function updateState(changes,scroll=false){state={...state,...changes};setURL(true);renderLibrary();if(scroll)$c('#library-title').focus({preventScroll:true});if(scroll)$c('#thu-vien').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}
  function renderFamilies(){
    $c('#family-grid').innerHTML=categories.map((c,i)=>`<a class="family-card" href="${productsPath(language)}?group=${c.slug}#thu-vien" data-family="${c.slug}"><span class="family-number">${c.number}</span><img src="${imageURL(familyPhotos[i])}" alt="${escapeHTML(c[language])} — HotPrint" width="360" height="240" loading="lazy"><h3>${escapeHTML(c[language])}</h3><p>${familyUses[language][i]}</p><span class="family-bottom">${txt('groupLink')}${icon('arrow')}</span></a>`).join('');
  }
  function renderLibrary(){
    const group=categories.find(c=>c.slug===state.group);
    const terms=normalize(state.q).trim().split(/\s+/).filter(Boolean);
    const matches=products.filter(p=>(!group||p.group===group.icon)&&terms.every(term=>normalize([p.vi,p.en,p.id,categories.find(c=>c.icon===p.group).vi,categories.find(c=>c.icon===p.group).en].join(' ')).includes(term)));
    const pages=Math.max(1,Math.ceil(matches.length/12));state.page=Math.min(state.page,pages);setURL();
    $c('#catalog-query').value=state.q;$c('#catalog-group').value=state.group;
    $c('#filter-badge').textContent=state.group?'1':'';
    $c('#clear-filters').hidden=!state.q&&!state.group;
    const first=(state.page-1)*12,last=Math.min(first+12,matches.length);
    $c('#catalog-status').textContent=(language==='vi'?`${matches.length?first+1:0}–${last} / ${matches.length} mẫu`:`${matches.length?first+1:0}–${last} of ${matches.length} samples`)+(state.q?` · “${state.q}”`:'')+(group?` · ${group[language]}`:'');
    $c('#product-grid').innerHTML=matches.slice(first,last).map(p=>{const title=escapeHTML(p[language]),groupName=categories.find(c=>c.icon===p.group)[language];return `<article class="product-card"><button class="product-photo" data-detail="${p.id}" aria-label="${txt('detail')}: ${title}" aria-haspopup="dialog"><img src="${imageURL(p.images[0])}" width="720" height="480" alt="${title} — HotPrint" loading="lazy"><span class="photo-open" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M9 12h6m-3-3v6"/></svg></span></button><div class="product-caption"><div class="product-meta"><span>${groupName}</span><span>${p.id}</span></div><h3><button data-detail="${p.id}" aria-haspopup="dialog">${title}</button></h3><div class="product-card-actions"><button data-detail="${p.id}" aria-haspopup="dialog">${txt('detail')}${icon('arrow')}</button><button data-request="sample" data-model="${p.id}" aria-label="${txt('sample')}: ${title}">${txt('sample')} +</button></div></div></article>`;}).join('');
    $c('#catalog-empty').hidden=matches.length>0;
    $c('#catalog-pagination').setAttribute('aria-label',txt('pagination'));
    $c('#catalog-pagination').innerHTML=pages>1?`<button data-page="${state.page-1}" aria-label="${txt('prev')}" ${state.page===1?'disabled':''}>←</button>`+Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" aria-label="${txt('page')} ${i+1}" ${state.page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')+`<button data-page="${state.page+1}" aria-label="${txt('next')}" ${state.page===pages?'disabled':''}>→</button>`:'';
  }
  function renderGallery(){
    const p=selectedProduct;if(!p)return;
    $c('#detail-title').textContent=p[language];$c('#detail-group').textContent=categories.find(c=>c.icon===p.group)[language];$c('#detail-ref').textContent=txt('ref')+' / '+p.id;
    const img=$c('#detail-image');img.src=imageURL(p.images[imageIndex],true);img.alt=p[language]+` — ${txt('photo')} ${imageIndex+1}`;img.hidden=false;
    $c('.detail-image-wrap .image-unavailable')?.remove();
    $c('#detail-original').href=img.src;$c('#detail-count').textContent=`${imageIndex+1} / ${p.images.length}`;
    for(const [id,key]of [['gallery-prev','prevImage'],['gallery-next','nextImage']]){$c('#'+id).hidden=p.images.length===1;$c('#'+id).setAttribute('aria-label',txt(key));}
    $c('#detail-thumbs').innerHTML=p.images.map((id,i)=>`<button data-image="${i}" aria-label="${txt('photo')} ${i+1}" aria-pressed="${i===imageIndex}"><img src="${imageURL(id)}" alt="" width="70" height="50"></button>`).join('');
    $c('#detail-quote').dataset.model=p.id;$c('#detail-sample').dataset.model=p.id;
  }
  function localize(){
    document.querySelectorAll('[data-c]').forEach(el=>el.textContent=txt(el.dataset.c));
    document.querySelectorAll('[data-c-alt]').forEach(el=>el.alt=txt(el.dataset.cAlt));
    $c('#catalog-query').placeholder=txt('placeholder');
    $c('#catalog-group').replaceChildren(new Option(txt('allGroups'),''),...categories.map(c=>new Option(c[language],c.slug)));
    renderFamilies();state=readState();renderLibrary();renderGallery();
  }
  $c('#catalog-search').addEventListener('submit',e=>{e.preventDefault();updateState({q:$c('#catalog-query').value.trim(),page:1});});
  $c('#catalog-group').addEventListener('change',e=>updateState({group:e.target.value,page:1}));
  for(const id of ['clear-filters','empty-clear'])$c('#'+id).addEventListener('click',()=>updateState({q:'',group:'',page:1}));
  document.addEventListener('click',e=>{
    const family=e.target.closest('[data-family]');if(family&&!e.ctrlKey&&!e.metaKey){e.preventDefault();updateState({group:family.dataset.family,page:1,q:''},true);}
    const detail=e.target.closest('[data-detail]');if(detail){selectedProduct=products.find(p=>p.id===detail.dataset.detail);imageIndex=0;renderGallery();openDialog($c('#product-detail'),detail);}
    const page=e.target.closest('.catalog-pagination [data-page]');if(page&&!page.disabled)updateState({page:Number(page.dataset.page)},true);
    const thumb=e.target.closest('[data-image]');if(thumb){imageIndex=Number(thumb.dataset.image);renderGallery();$c(`#detail-thumbs [data-image="${imageIndex}"]`).focus();}
  });
  $c('#gallery-prev').addEventListener('click',()=>{imageIndex=(imageIndex-1+selectedProduct.images.length)%selectedProduct.images.length;renderGallery();});
  $c('#gallery-next').addEventListener('click',()=>{imageIndex=(imageIndex+1)%selectedProduct.images.length;renderGallery();});
  $c('#mobile-filter').addEventListener('click',e=>{
    $c('#filter-options').innerHTML=[{slug:'',[language]:txt('allGroups')},...categories].map(c=>`<label><input type="radio" name="family" value="${c.slug}" ${state.group===c.slug?'checked':''}><span>${c[language]}</span></label>`).join('');
    openDialog($c('#filter-dialog'),e.currentTarget);
  });
  $c('#reset-mobile-filter').addEventListener('click',()=>{$c('#filter-options input[value=""]').checked=true;});
  $c('#filter-form').addEventListener('submit',e=>{e.preventDefault();const group=new FormData(e.currentTarget).get('family')||'';$c('#filter-dialog').close();updateState({group,page:1});});
  document.addEventListener('error',e=>{if(e.target.tagName!=='IMG'||!e.target.src.includes('/assets/products/'))return;const img=e.target;img.hidden=true;const holder=img.parentElement;if(!holder.querySelector('.image-unavailable')){const fallback=document.createElement('span');fallback.className='image-unavailable';fallback.textContent=txt('unavailable');holder.append(fallback);}},true);
  document.addEventListener('hotprint:language',localize);
  localize();
})();
